// GÉNÉRÉ à partir des tracés vectoriels du design v2 (SmartFarm-Interface-v2.pdf), en dp (écran de 360 dp).
// Ne pas éditer à la main. Chaque icône vit dans une boîte de 24x24 dp ; (dx, dy) = position du tracé dans cette boîte.
// Traits à bouts et jonctions arrondis. Une couleur explicite n'est posée que si elle diffère de la couleur de l'icône.
import 'dart:ui';

class SfLayer {
  const SfLayer(this.path, this.fill, this.strokeWidth, this.color, {this.clip});
  final Path path;
  final bool fill;
  final double strokeWidth;
  final Color? color; // null = couleur de l'icône
  final Path? clip; // si présent, le calque est découpé par ce chemin (ex. anneau pointillé)
}

/// Couronne de l'anneau pointillé « en cours » : rayon intérieur 11 dp, rayon extérieur 14 dp, centre (16,3 ; 16,3).
final Path _couronneAnneau = Path()
  ..fillType = PathFillType.evenOdd
  ..addOval(Rect.fromCircle(center: const Offset(16.3, 16.3), radius: 14))
  ..addOval(Rect.fromCircle(center: const Offset(16.3, 16.3), radius: 11));

class SfIconData {
  const SfIconData(this.boxWidth, this.boxHeight, this.dx, this.dy, this.layers);
  final double boxWidth, boxHeight, dx, dy;
  final List<SfLayer> layers;
}

